def get_sequence_length(proteinID: str) -> int:
    if proteinID[0] == 'P':
        return 100
    elif proteinID[0] == 'Q':
        return 150
    else:
        return 200

def average_score(scores: List[int]) -> float:
    if not scores:
        return 0.00
    total = sum(scores)
    average = total / len(scores)
    return round(average, 2)

def handle_pid_redirect(source_pid, destination_pid):
    source_type = source_pid['pid_type']
    destination_type = destination_pid['pid_type']

    if source_type == destination_type:
        return {
            'status': 301,
            'message': 'Moved Permanently.',
            'location': f'/records/{destination_pid["pid_value"]}'
        }
    else:
        return {
            'status': 400,
            'message': 'PID types do not match.'
        }

from typing import List, Dict, Union

def create_category_index(categories: List[Dict[str, Union[int, str]]]) -> Dict[int, Dict[str, Union[int, str]]]:
    return {category['id']: category for category in categories}
